css:
.cv-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.cv-stage canvas { touch-action: none; cursor: grab; }
.cv-stage canvas.holding { cursor: grabbing; }
.cv-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.6em; }
.cv-facts { display: grid; grid-template-columns: auto 1fr; gap: 4px 12px; margin: 0; font-size: 18px; }
.cv-facts dt { font-weight: 800; color: var(--accent-ink, #8a5a00); }
.cv-facts dd { margin: 0; }

